printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t10:00\t11:00\tz\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
o=$(BOOKINGS=$t bash src/list.sh --room 2>"$t.err"); rc=$?
[ $rc = 2 ] || { echo "list --room without value: exit $rc, want 2"; fail=1; }
[ -z "$o" ] || { echo "list --room without value: stdout not empty"; fail=1; }
[ "$(cat "$t.err")" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value: stderr"; fail=1; }
rm -f "$t" "$t.err"; exit $fail

